		{
			text = [=[La {link:defias-brotherhood}Confrérie défias{/link}, la lettre du messager]=],
		},
		{
			text = [=[La {link:defias-brotherhood}Confrérie défias{/link}, la route du traître]=],
		},
		{ text = "Messager pour la {link:westfall}Marche de l'Ouest{/link}" },
		{
			text = [=[Messager pour la {link:westfall}Marche de l'Ouest{/link}, sa réponse à {link:lakeshire}Lakeshire{/link}]=],
		},
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "l'homme qu'il traque" },
		{ id = "captain-danuvin", name = "Capitaine Danuvin", note = "son officier" },
		{ id = "scout-galiaan", name = "Éclaireur Galiaan", note = "son éclaireur le plus fiable" },
