			text = [=[L'agent Kearnen sert le {link:si-7}SI:7{/link}, les espions de {link:stormwind-city}Stormwind{/link}. Depuis des semaines, elle surveille une tour de guet abandonnée au sud-est de la {link:sentinel-hill}Colline des sentinelles{/link}, dont les {link:defias-brotherhood}Défias{/link} ont fait une base pour les marchandises passées en contrebande le long de la route des {link:redridge-mountains}Carmines{/link}. Ce qu'elle a vu la trouble. Un chargement arriva du {link:duskwood}Bois de la Pénombre{/link} avec un coffre, et avec lui vinrent des gardes qui ne sont pas humains.]=],
		},
		{
			title = "Importance",
			text = [=[La surveillance de Kearnen dévoile un commerce plus sombre entre les mains de la Confrérie. Le coffre de la tour appartient au {link:defias-brotherhood}Défias{/link} Klaven Mortwake, et ses secrets mènent loin au sud, jusqu'aux trolls de la {link:stranglethorn-vale}vallée de Strangleronce{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle tient un journal de tout ce qu'elle voit à la tour.
• Elle attend que le {link:si-7}SI:7{/link} envoie un autre agent.]=],
		},
	},
	mentions = {
		{ text = "Mathias et les {link:defias-brotherhood}Défias{/link}" },
		{ text = "La tour de Klaven" },
	},
	bonds = {
		{ id = "master-mathias-shaw", name = "Maître Mathias Shaw", note = "son maître au SI:7" },
	},
})

Translate("frFR", "alba-fairmoon", {
	title = "Alba Fairmoon",
	subtitle = "Enquêtrice de la terre empoisonnée",
	found = "L'auberge de la Colline des sentinelles",
	hint = [=[Parlez à l'elfe de la nuit qui étudie le mal du sol de la Marche de l'Ouest.]=],
	allegiance = "Darnassus",
	aliases = { "Alba" },
	sections = {
		{
			title = "Résumé",
			text = [=[Alba Fairmoon est une {link:night-elves}elfe de la nuit{/link} de {link:darnassus}Darnassus{/link} venue dans la {link:westfall}Marche de l'Ouest{/link} pour comprendre pourquoi sa terre se meurt. Elle commença par l'eau, en analysant les puits des fermes, et les trouva pleins de métaux toxiques. Elle suivit le poison à travers les mines et la carrière, et enfin jusqu'à {link:moonbrook}Ruisselune{/link}, où elle trouva les signes de grands travaux sous la terre.]=],
		},
		{
			title = "Importance",
			text = [=[Alba craint que, si le poison n'est pas arrêté, rien ne pousse plus dans la {link:westfall}Marche de l'Ouest{/link} pendant des décennies, et que {link:stormwind-city}Stormwind{/link} connaisse la famine.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle analysa les puits de la {link:the-jansen-stead}ferme des Jansen{/link} et de la {link:the-molsen-farm}ferme des Molsen{/link}.
• Elle remonta le poison jusqu'à une forge cachée dans les {link:the-deadmines}Mortemines{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La forge d'en bas",
			hint = "Suivez le poison des puits jusqu'à sa source.",
			text = [=[Avec des explosifs fabriqués à {link:stormwind-city}Stormwind{/link}, la forge des {link:the-deadmines}Mortemines{/link} fut détruite. Alba attendit dans les collines derrière {link:moonbrook}Ruisselune{/link} de voir la chose accomplie. Ensuite, elle parla avec tristesse d'un royaume qui semblait tenir davantage à ses guerres qu'à la subsistance de son propre peuple.]=],
		},
	},
	mentions = {
		{ text = "L'analyse des puits" },
		{ text = "Branchies de {link:murlocs}murloc{/link}" },
		{ text = "L'état des mines" },
		{ text = "Espionnage à {link:moonbrook}Ruisselune{/link}" },
		{ text = "Consultation explosive" },
		{ text = "Destruction dans les {link:the-deadmines}Mortemines{/link}" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "défend la terre qu'elle étudie" },
	},
})

Translate("frFR", "ozwin-ironsprocket", {
	title = "Ozwin Ironsprocket",
	subtitle = "Bricoleur de Gnomeregan",
	found = "L'écurie de la ferme des Saldean",
	hint = [=[Cherchez dans l'écurie de la ferme des Saldean un gnome qui se cache.]=],
	allegiance = "Exilés de Gnomeregan",
	aliases = { "Ozwin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ozwin Ironsprocket est un {link:gnomes}gnome{/link} venu tout droit d'{link:ironforge}Ironforge{/link} quand il entendit parler des {link:harvest-golems}golems des moissons{/link} devenus incontrôlables dans la {link:westfall}Marche de l'Ouest{/link}. Il comptait les recalibrer. Les machines se révélèrent bien plus agressives que ses calculs ne le prévoyaient, et elles le poursuivirent jusque dans l'écurie de la ferme des {link:farmer-saldean}Saldean{/link}, où il se cache depuis.]=],
		},
		{
			title = "Importance",
			text = [=[Ozwin est le seul dans la {link:westfall}Marche de l'Ouest{/link} à chercher à comprendre les {link:harvest-golems}golems des moissons{/link} plutôt qu'à simplement les détruire.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie les pièces des golems brisés.
• Il construisit un appareil capable de prendre le contrôle des mécanismes des golems, ne serait-ce qu'un instant.]=],
		},
	},
	mentions = {
		{ text = "Moissonner les moissonneurs" },
		{ text = "Moissonner les moissonneurs" },
	},
	bonds = {
		{ id = "farmer-saldean", name = "Fermier Saldean", note = "l'abrite dans son écurie" },
	},
})

Translate("frFR", "harvest-golems", {
	title = "Golems des moissons",
	aliases = { "golems des moissons", "Golem des moissons", "golem des moissons", "Guetteurs des moissons", "Guetteur des moissons", "machines des moissons" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les golems des moissons sont de grandes machines de fer construites pour travailler les champs de la {link:westfall}Marche de l'Ouest{/link}. Ils furent faits pour moissonner, semer et veiller sur les récoltes. Aujourd'hui, ils arpentent les fermes abandonnées sans maître et chassent quiconque s'approche, comme si les fermiers eux-mêmes étaient des nuisibles à ôter des rangs.]=],
		},
		{
			title = "Espèces",
			text = [=[• Les {b}golems des moissons rouillés{/b} et les {b}golems des moissons{/b} sont les plus petits et les plus faibles.
• Les {b}Guetteurs des moissons{/b} montent la garde sur les champs, comme leur nom l'indique.
• Les {b}Faucheurs des moissons{/b} sont les plus grands et les plus dangereux. Ils arpentent les champs brûlés de l'acre mort.
• {b}Le Foe Reaper 4000{/b} est une machine unique, bien plus forte que les autres, qui arpente les champs des plaines de l'ouest.]=],
		},
		{
			title = "En ces jours",
			text = [=[Aucun fermier ne peut dire avec certitude comment les machines se sont déréglées. Beaucoup dans la {link:westfall}Marche de l'Ouest{/link} accusent la {link:defias-brotherhood}Confrérie défias{/link}, dont les alliés gobelins construisent et commandent des golems dans les profondeurs des {link:the-deadmines}Mortemines{/link}. Le {link:gnomes}gnome{/link} {link:ozwin-ironsprocket}Ozwin Ironsprocket{/link} a étudié leurs pièces et appris à en prendre le contrôle, mais seulement pour un instant. Le fantôme du phare de l'Ouest nourrit sa flamme avec l'huile tirée de leurs articulations. Le fermier {link:farmer-saldean}Saldean{/link} veut simplement qu'ils disparaissent.]=],
		},
	},
})
